(* [comment removed for export] *)
Lemma fmt_pieces : forall m A l1 c nx l2,
  cstr_at m A (zb8 (l1 ++ [37; c] ++ nx :: l2)) ->
  bytes_at asegs m A (zb8 l1) /\ bytes_at asegs m (A + Z.of_nat (length l1)) (zb8 [37; c; nx])
  /\ bytes_at asegs m (A + Z.of_nat (length l1) + 2) (zb8 (nx :: l2))
  /\ bytes_at asegs m (A + Z.of_nat (length l1) + 2 + Z.of_nat (length (nx :: l2))) [z8].
Proof.
